  ?s rdfs:label ?label .
  FILTER(?label IN ("Chiller02","CondPump01","CondPump02"))
}

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(str(?o) LIKE "%Chiller02%" || str(?o) LIKE "%CondPump%")
}

SELECT ?pt ?label ?tid WHERE {
  ?pt ref:hasTimeseriesId ?tid .
  ?pt rdfs:label ?label .
  FILTER(CONTAINS(STR(?pt), "CondPump") || CONTAINS(STR(?pt), "Chiller02"))
}

